import '../utils/story_markers.dart';

/// Placement Test PT-V1.1 instrument contract (`DATA_MODEL.md` §6). Mirrors
/// the app-safe bank generated by `tools/research/bin/build_placement.js`
/// and the placement rules in `firestore.rules`, so a malformed bank is
/// rejected before any write the rules would deny. Nothing here is, or is
/// derived from, the answer key (which never reaches the app).
const String kPlacementInstrumentId = 'vocably-placement';
const String kPlacementInstrumentVersion = 'PT-V1.1';
const String kPlacementBankAsset = 'assets/placement/placement_bank_pt_v1_1.json';
const List<String> kPlacementBands = ['A1', 'A2', 'B1', 'B2', 'C1'];
const int kPlacementItemsPerBand = 10;
const int kPlacementItemCount = 50;

/// Fixed options A–D (never shuffled) plus E "Saya tidak tahu", always last.
const List<String> kPlacementOptionIds = ['A', 'B', 'C', 'D'];
const String kPlacementDontKnowId = 'E';
const String kPlacementDontKnowText = 'Saya tidak tahu';
const List<String> kPlacementAnswerIds = ['A', 'B', 'C', 'D', 'E'];

class PlacementInstrumentException implements Exception {
  const PlacementInstrumentException(this.message);

  final String message;

  @override
  String toString() => 'PlacementInstrumentException: $message';
}

class PlacementOption {
  const PlacementOption({required this.id, required this.text});

  final String id;
  final String text;
}

/// One item: an English sentence with one marked target word
/// (`[[word|form]]`, parsed with the shared story-marker parser) and its
/// four fixed Indonesian options.
class PlacementItem {
  const PlacementItem({
    required this.id,
    required this.band,
    required this.number,
    required this.sentenceMarkup,
    required this.options,
  });

  final String id;
  final String band;
  final int number;
  final String sentenceMarkup;
  final List<PlacementOption> options;

  List<StorySegment> get segments => parseStoryMarkers(sentenceMarkup);
}

class PlacementInstrument {
  PlacementInstrument({
    required this.version,
    required this.items,
  }) : _byId = {for (final item in items) item.id: item};

  final String version;
  final List<PlacementItem> items;
  final Map<String, PlacementItem> _byId;

  PlacementItem? itemById(String id) => _byId[id];

  List<PlacementItem> itemsForBand(String band) => [
    for (final item in items)
      if (item.band == band) item,
  ];

  /// Strict parse of the bank JSON; any deviation throws.
  factory PlacementInstrument.fromJson(Object? json) {
    if (json is! Map) throw const PlacementInstrumentException('bank is not an object');
    if (json['schemaVersion'] != 1 ||
        json['instrumentId'] != kPlacementInstrumentId ||
        json['instrumentVersion'] != kPlacementInstrumentVersion) {
      throw const PlacementInstrumentException('unsupported bank id or version');
    }
    if ((json['bands'] as List?)?.join(',') != kPlacementBands.join(',') ||
        json['itemsPerBand'] != kPlacementItemsPerBand) {
      throw const PlacementInstrumentException('unexpected bands');
    }
    final dontKnow = json['dontKnowOption'];
    if (dontKnow is! Map ||
        dontKnow['id'] != kPlacementDontKnowId ||
        dontKnow['text'] != kPlacementDontKnowText) {
      throw const PlacementInstrumentException('unexpected "Saya tidak tahu" option');
    }
    final rawItems = json['items'];
    if (rawItems is! List || rawItems.length != kPlacementItemCount) {
      throw const PlacementInstrumentException('expected 50 items');
    }
    final items = <PlacementItem>[];
    final ids = <String>{};
    for (final raw in rawItems) {
      if (raw is! Map) throw const PlacementInstrumentException('item is not an object');
      final id = raw['id'];
      final band = raw['band'];
      final number = raw['number'];
      final markup = raw['sentenceMarkup'];
      final rawOptions = raw['options'];
      if (id is! String || !ids.add(id)) {
        throw const PlacementInstrumentException('missing or duplicate item id');
      }
      if (band is! String || !kPlacementBands.contains(band) || number is! int) {
        throw PlacementInstrumentException('$id: invalid band or number');
      }
      if (markup is! String ||
          parseStoryMarkers(markup).whereType<MarkedStorySegment>().length != 1) {
        throw PlacementInstrumentException('$id: needs exactly one marked word');
      }
      if (rawOptions is! List || rawOptions.length != kPlacementOptionIds.length) {
        throw PlacementInstrumentException('$id: needs options A–D');
      }
      final options = <PlacementOption>[];
      for (var i = 0; i < rawOptions.length; i++) {
        final o = rawOptions[i];
        if (o is! Map ||
            o['id'] != kPlacementOptionIds[i] ||
            o['text'] is! String ||
            (o['text'] as String).trim().isEmpty ||
            o.length != 2) {
          throw PlacementInstrumentException('$id: invalid option ${i + 1}');
        }
        options.add(PlacementOption(id: o['id'] as String, text: o['text'] as String));
      }
      items.add(
        PlacementItem(id: id, band: band, number: number, sentenceMarkup: markup, options: options),
      );
    }
    for (final band in kPlacementBands) {
      if (items.where((i) => i.band == band).length != kPlacementItemsPerBand) {
        throw PlacementInstrumentException('band $band needs 10 items');
      }
    }
    return PlacementInstrument(version: kPlacementInstrumentVersion, items: items);
  }
}
